INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-kinematics-001', 'phy', 'กลศาสตร์', 'การเคลื่อนที่แนวตรง', '[]', 'hard', 'วิเคราะห์การเคลื่อนที่แนวตรง 3 ช่วง (เร่ง-คงที่-หน่วง) หาระยะทางรวม (ระดับค่าย สอวน)', NULL, 'mc5', 'รถยนต์เริ่มจากหยุดนิ่ง เร่งความเร็วสม่ำเสมอด้วยอัตรา 2 m/s² เป็นเวลา 5 วินาที จากนั้นแล่นด้วยความเร็วคงที่เป็นเวลา 10 วินาที แล้วจึงลดความเร็วสม่ำเสมอจนหยุดภายใน 4 วินาที ระยะทางรวมทั้งหมดเท่ากับกี่เมตร', '["120 เมตร", "135 เมตร", "145 เมตร", "155 เมตร", "165 เมตร"]', '145 เมตร', '["ช่วงเร่ง: v=2×5=10 m/s, ระยะทาง=½×2×5²=25 เมตร", "ช่วงคงที่: ระยะทาง=10×10=100 เมตร", "ช่วงหน่วง: ระยะทาง=½×(10+0)×4=20 เมตร", "รวมทั้งหมด = 25+100+20 = 145 เมตร"]', '["ลืมคำนวณความเร็วปลายของช่วงแรกก่อนนำไปใช้ในช่วงคงที่และช่วงหน่วง"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-newtonlaw-001', 'phy', 'กลศาสตร์', 'แรงและกฎการเคลื่อนที่', '[]', 'hard', 'วิเคราะห์ระบบมวลเชื่อมด้วยเชือกผ่านรอก (Atwood machine) (ระดับค่าย สอวน)', NULL, 'mc5', 'มวล 3 กิโลกรัม และ 5 กิโลกรัม ผูกติดกันด้วยเชือกเบาคล้องผ่านรอกลื่นไร้มวล ปล่อยจากหยุดนิ่ง แรงตึงในเส้นเชือกเท่ากับกี่นิวตัน (g=10 m/s²)', '["30 นิวตัน", "32.5 นิวตัน", "35 นิวตัน", "37.5 นิวตัน", "40 นิวตัน"]', '37.5 นิวตัน', '["ความเร่งของระบบ a = (m2-m1)g/(m1+m2) = (5-3)×10/8 = 2.5 m/s²", "แรงตึงเชือก T = m1(g+a) = 3×(10+2.5) = 37.5 นิวตัน (เช็คอีกฝั่ง: T=m2(g-a)=5×7.5=37.5 นิวตัน ตรงกัน)"]', '["ใช้ g เฉยๆ แทนความเร่งจริงของระบบในการหาแรงตึง"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-wave-001', 'phy', 'คลื่นกล และแสง', 'คลื่น', '[]', 'hard', 'หาความถี่ของคลื่นนิ่งบนเส้นเชือกที่ฮาร์มอนิกที่กำหนด (ระดับค่าย สอวน)', NULL, 'mc5', 'เส้นเชือกยาว 2 เมตร ตรึงปลายทั้งสองข้าง เกิดคลื่นนิ่งฮาร์มอนิกที่ 3 ถ้าอัตราเร็วคลื่นบนเส้นเชือกเท่ากับ 40 เมตรต่อวินาที ความถี่ของคลื่นนี้เท่ากับกี่เฮิรตซ์', '["15 Hz", "20 Hz", "25 Hz", "30 Hz", "40 Hz"]', '30 Hz', '["ความยาวคลื่นที่ฮาร์มอนิกที่ n: λ = 2L/n = 2(2)/3 = 4/3 เมตร", "ความถี่ f = v/λ = 40/(4/3) = 30 Hz"]', '["ใช้สูตร λ=2L (ฮาร์มอนิกที่ 1) แทนที่จะหารด้วยลำดับฮาร์มอนิก n=3"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-electrostatics-001', 'phy', 'ไฟฟ้า แม่เหล็ก และคลื่นแม่เหล็กไฟฟ้า', 'ไฟฟ้าสถิต', '[]', 'hard', 'หาตำแหน่งสมดุลไฟฟ้าสถิตระหว่างประจุสองจุด (ระดับค่าย สอวน)', NULL, 'mc5', 'ประจุ +4 ไมโครคูลอมบ์ และ +9 ไมโครคูลอมบ์ วางห่างกัน 10 เซนติเมตร จุดที่สนามไฟฟ้ารวมมีค่าเป็นศูนย์อยู่ห่างจากประจุ 4 ไมโครคูลอมบ์เท่าใด', '["3 เซนติเมตร", "4 เซนติเมตร", "5 เซนติเมตร", "6 เซนติเมตร", "7 เซนติเมตร"]', '4 เซนติเมตร', '["ให้ x คือระยะจากประจุ 4 μC ตั้งสมการ √q1/x = √q2/(d-x)", "√4/x = √9/(10-x) → 2/x = 3/(10-x) → 2(10-x)=3x → x=4 เซนติเมตร"]', '["ตั้งสมการโดยไม่ถอดรากที่สองของประจุก่อนเทียบสัดส่วน"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-heat-001', 'phy', 'อุณหพลศาสตร์และสมบัติเชิงกลของสาร', 'ความร้อนและแก๊ส', '[]', 'hard', 'หาอุณหภูมิสมดุลจากการผสมของเหลวสองอุณหภูมิ (calorimetry) (ระดับค่าย สอวน)', NULL, 'mc5', 'นำน้ำ 200 กรัม อุณหภูมิ 80°C ผสมกับน้ำ 300 กรัม อุณหภูมิ 20°C (ไม่มีการสูญเสียความร้อนสู่ภายนอก) อุณหภูมิสุดท้ายของน้ำผสมเท่ากับกี่องศาเซลเซียส', '["38°C", "40°C", "42°C", "44°C", "46°C"]', '44°C', '["ความร้อนที่น้ำร้อนคายเท่ากับความร้อนที่น้ำเย็นรับ: 200(80-Tf) = 300(Tf-20)", "16000-200Tf = 300Tf-6000 → 22000=500Tf → Tf=44°C"]', '["ใช้มวลทั้งสองส่วนเท่ากันในการถ่วงน้ำหนักโดยลืมว่ามวลไม่เท่ากัน"]');
INSERT OR IGNORE INTO questions (id, subject, section, topic, integrates_with, difficulty, skill_measured, skill_type, format, question, choices, answer, solution_steps, common_mistakes)
VALUES ('phy-atomic-001', 'phy', 'ฟิสิกส์แผนใหม่', 'ฟิสิกส์อะตอม', '[]', 'hard', 'ใช้ปรากฏการณ์โฟโตอิเล็กทริกหาพลังงานจลน์สูงสุดของอิเล็กตรอน (ระดับค่าย สอวน)', NULL, 'mc5', 'โลหะชนิดหนึ่งมีฟังก์ชันงาน (work function) เท่ากับ 2.0 eV เมื่อฉายแสงความยาวคลื่น 400 นาโนเมตรลงบนผิวโลหะ พลังงานจลน์สูงสุดของอิเล็กตรอนที่หลุดออกมาเท่ากับกี่ eV (กำหนด hc=1240 eV·nm)', '["0.9 eV", "1.0 eV", "1.1 eV", "1.2 eV", "1.3 eV"]', '1.1 eV', '["พลังงานโฟตอน E = hc/λ = 1240/400 = 3.1 eV", "พลังงานจลน์สูงสุด KE = E - W = 3.1 - 2.0 = 1.1 eV"]', '["ลืมลบด้วยฟังก์ชันงานของโลหะ ตอบพลังงานโฟตอนเฉยๆ"]');
